BEGIN;
INSERT INTO legal_builder.permission_definition(code,name,description,created_at) VALUES
('WORKFLOW_READ','Đọc quy trình','Xem phiên bản quy trình và các lần thực hiện bước',clock_timestamp()),
('WORKFLOW_MANAGE','Quản lý quy trình','Gán quy trình và kích hoạt lần thực hiện bước',clock_timestamp()),
('WORKFLOW_GATE_DECIDE','Quyết định cổng','Hoàn thành, chặn hoặc miễn cổng quy trình',clock_timestamp());
CREATE TABLE legal_builder.workflow_definition(id uuid PRIMARY KEY,code text NOT NULL UNIQUE,name text NOT NULL,created_at timestamptz NOT NULL,created_by_user_id uuid NOT NULL REFERENCES legal_builder.user_account(id),CONSTRAINT ck_workflow_definition_text CHECK(btrim(code)<>'' AND btrim(name)<>''));
CREATE TABLE legal_builder.workflow_version(id uuid PRIMARY KEY,definition_id uuid NOT NULL REFERENCES legal_builder.workflow_definition(id),version_code text NOT NULL,status_code text NOT NULL,effective_from timestamptz,effective_to timestamptz,approval_basis text,configuration jsonb NOT NULL,created_at timestamptz NOT NULL,created_by_user_id uuid NOT NULL REFERENCES legal_builder.user_account(id),approved_at timestamptz,approved_by_user_id uuid REFERENCES legal_builder.user_account(id),UNIQUE(definition_id,version_code),CONSTRAINT ck_workflow_version_status CHECK(status_code IN('DRAFT','APPROVED','RETIRED')),CONSTRAINT ck_workflow_version_config CHECK(jsonb_typeof(configuration)='object'),CONSTRAINT ck_workflow_version_dates CHECK(effective_to IS NULL OR effective_from IS NULL OR effective_to>effective_from),CONSTRAINT ck_workflow_version_approval CHECK(status_code='DRAFT' OR(approved_at IS NOT NULL AND approved_by_user_id IS NOT NULL AND btrim(coalesce(approval_basis,''))<>'')));
CREATE TABLE legal_builder.workflow_stage_definition(workflow_version_id uuid NOT NULL REFERENCES legal_builder.workflow_version(id),stage_code text NOT NULL,name text NOT NULL,stage_order integer NOT NULL,repeatable boolean NOT NULL DEFAULT true,parallel_allowed boolean NOT NULL DEFAULT false,applicability_expression text,gate_configuration jsonb NOT NULL DEFAULT '{}'::jsonb,PRIMARY KEY(workflow_version_id,stage_code),UNIQUE(workflow_version_id,stage_order),CONSTRAINT ck_workflow_stage_order CHECK(stage_order>0),CONSTRAINT ck_workflow_stage_text CHECK(btrim(stage_code)<>'' AND btrim(name)<>''),CONSTRAINT ck_workflow_stage_gate CHECK(jsonb_typeof(gate_configuration)='object'));
CREATE TABLE legal_builder.project_workflow(project_id uuid PRIMARY KEY REFERENCES legal_builder.legal_document_project(id),workflow_version_id uuid NOT NULL REFERENCES legal_builder.workflow_version(id),assigned_at timestamptz NOT NULL,assigned_by_user_id uuid NOT NULL REFERENCES legal_builder.user_account(id),migration_decision text);
CREATE TABLE legal_builder.workflow_stage_instance(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES legal_builder.legal_document_project(id),workflow_version_id uuid NOT NULL REFERENCES legal_builder.workflow_version(id),stage_code text NOT NULL,sequence integer NOT NULL,status_code text NOT NULL,gate_result_code text NOT NULL DEFAULT 'PENDING',assignee_membership_id uuid REFERENCES legal_builder.project_membership(id),started_at timestamptz,completed_at timestamptz,return_reason text,recorded_at timestamptz NOT NULL,recorded_by_user_id uuid NOT NULL REFERENCES legal_builder.user_account(id),UNIQUE(project_id,stage_code,sequence),FOREIGN KEY(workflow_version_id,stage_code) REFERENCES legal_builder.workflow_stage_definition(workflow_version_id,stage_code),CONSTRAINT ck_stage_instance_sequence CHECK(sequence>0),CONSTRAINT ck_stage_instance_status CHECK(status_code IN('PLANNED','ACTIVE','BLOCKED','COMPLETED','CANCELLED')),CONSTRAINT ck_stage_instance_gate CHECK(gate_result_code IN('PENDING','PASSED','FAILED','WAIVED')),CONSTRAINT ck_stage_instance_time CHECK(completed_at IS NULL OR(started_at IS NOT NULL AND completed_at>=started_at)),CONSTRAINT ck_stage_instance_completion CHECK(status_code<>'COMPLETED' OR(completed_at IS NOT NULL AND gate_result_code IN('PASSED','WAIVED'))));
ALTER TABLE legal_builder.review_round ADD COLUMN workflow_stage_instance_id uuid REFERENCES legal_builder.workflow_stage_instance(id);
CREATE INDEX ix_stage_instance_project_status ON legal_builder.workflow_stage_instance(project_id,status_code,recorded_at);
COMMIT;
